CREATE TEMPORARY VIEW request_advv_benchmark_preprocess_${grass_region_without_quote} AS
SELECT
    -- Preprocess data to original srdi_mart.dws_sr_request_level_ads_type_advv_di dimensions
    feature_group
    ,user_id
    ,request_id
    ,product_type
    ,voucher_type
    ,ads_id
    ,item_id
    ,campaign_id

    ,SUM(revenue_usd) AS revenue_usd
    ,SUM(broad_gmv_usd) AS broad_gmv_usd
    ,SUM(broad_gmv_usd) AS gmv_for_ratio
    ,SUM(ads_gmv_usd) AS ads_gmv_usd
    ,AVG(target_cir) AS target_cir
    ,SUM(direct_advv_cost) AS direct_advv_cost
    ,SUM(broad_advv_cost) AS broad_advv_cost
    ,SUM(direct_advv_gmv) AS direct_advv_gmv
    ,SUM(broad_advv_gmv) AS broad_advv_gmv
    ,SUM(ads_click_cnt) AS ads_click_cnt
    ,SUM(ads_imp_cnt) AS ads_imp_cnt
    ,SUM(ads_order_cnt) AS ads_order_cnt
    ,SUM(ads_broad_order_cnt) AS ads_broad_order_cnt
    ,MAX(sum_deduction_price_usd) AS sum_deduction_price_usd
    ,MAX(sum_bid_price_usd) AS sum_bid_price_usd
    ,MAX(cnt_deduction_price) AS cnt_deduction_price
    ,MAX(cnt_bid_price) AS cnt_bid_price
    ,MAX(padvv) AS padvv
    ,SUM(ads_total_location) AS ads_total_location
    ,SUM(if(deduction_reason = 0, coalesce(ads_imp_cnt, 0), 0)) AS valid_ads_imp_cnt
FROM
    srdi_mart.dws_sr_data_warehouse_ads_request_benchmark_advv_1d
LATERAL VIEW
    EXPLODE(feature_groups) AS feature_group   
LATERAL VIEW
    EXPLODE(product_types) AS product_type
LATERAL VIEW
    EXPLODE(voucher_types) AS voucher_type
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND product_type != '__ALL__'
    AND feature_group != '__ALL__'
GROUP BY
    1,2,3,4,5,6,7,8;

