CREATE TEMPORARY VIEW feature_performance_${grass_region_without_quote} AS
SELECT
    CASE WHEN scenario_tag='DA_Cart_Unify' THEN 'Cart Unify'
        WHEN scenario_tag = 'dpm module Global Search business line Search' THEN 'Search'
        WHEN scenario_tag = 'DA_mpp_ymal-order_list' THEN 'My Purchase Page YMAL'
        WHEN scenario_tag = 'DA_odp_ymal-order_detail' THEN 'Order Detail Page YMAL'
        ELSE replace(scenario_tag,'DA_','') END AS feature_group
    ,SUM(imp_cnt) AS feature_total_imp_cnt
    ,SUM(click_cnt) AS feature_total_click_cnt
    ,SUM(order_cnt) AS feature_total_order_cnt
    ,SUM(gmv) AS feature_total_gmv
FROM
    srdi_mart.dws_sr_data_warehouse_platform_scenario_level_benchmark_1d
WHERE
    local_date = ${local_date}
    AND grass_region = ${grass_region}
    AND scenario_tag IN ('DA_Cart_Unify','DA_Daily Discover','DA_You May Also Like','dpm module Global Search business line Search','DA_Cart Recommendation','DA_mpp_ymal-order_list','DA_odp_ymal-order_detail','DA_Order Successful Recommendation','DA_Me YMAL','DA_Shop YMAL','DA_YMAL_Cart','DA_RCMD Unify')
    AND feature_detail = '__ALL__'
GROUP BY
    1
UNION ALL
SELECT
    's&r' AS feature_group
    ,SUM(imp_cnt) AS feature_total_imp_cnt
    ,SUM(click_cnt) AS feature_total_click_cnt
    ,SUM(order_cnt) AS feature_total_order_cnt
    ,SUM(gmv) AS feature_total_gmv
FROM
    srdi_mart.dws_sr_data_warehouse_platform_scenario_level_benchmark_1d
WHERE
    local_date = ${local_date}
    AND grass_region = ${grass_region}
    AND scenario_tag IN ('DA_Cart_Unify','DA_Daily Discover','DA_You May Also Like','dpm module Global Search business line Search')
    AND feature_detail = '__ALL__'
GROUP BY
    1
UNION ALL
SELECT
    rcmd_ab_bundle AS feature_group
    ,AVG(total_pv_imp) AS feature_total_imp_cnt
    ,AVG(total_pv_click) AS feature_total_click_cnt
    ,AVG(total_video_orders) AS feature_total_order_cnt
    ,AVG(total_video_gmv_usd) AS feature_total_gmv
FROM
    srdi_mart.ads_rcmd_onepage_ad_metrics_di
WHERE
    grass_date = ${local_date}
    AND grass_region = ${grass_region}
GROUP BY
    1
UNION ALL
SELECT
    'Livestream' AS feature_group
    ,0 AS feature_total_imp_cnt
    ,0 AS feature_total_click_cnt
    ,SUM(total_ls_order_fraction) AS feature_total_order_cnt
    ,SUM(gmv_usd) AS feature_total_gmv
FROM
    mp_content_oa.dwd_ls_order_omni_local_content_final_detail_di 
WHERE
    tz_type = 'local' 
    AND grass_region = ${grass_region}
    AND grass_date = ${local_date}
    AND order_cal_type = 'direct'
GROUP BY
    1;

--sql_divide_splitter--

CREATE TEMPORARY VIEW platform_total_${grass_region_without_quote} AS
SELECT
    SUM(imp_cnt) AS plt_total_imp_cnt
    ,SUM(click_cnt) AS plt_total_click_cnt
    ,SUM(order_cnt) AS plt_total_order_cnt
    ,SUM(gmv) AS plt_total_gmv
FROM
    srdi_mart.dws_sr_data_warehouse_platform_scenario_level_benchmark_1d
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND feature_detail = '__ALL__'
    AND scenario_tag = '__ALL__';

--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.ads_sr_data_warehouse_platform_scenario_ads_type_perf_summary_1d
PARTITION (
    grass_region = ${grass_region}
    ,local_date = ${local_date}
)
SELECT
    a.feature_group
    ,a.ads_type
    ,revenue_usd
    ,ads_gmv_usd
    ,broad_gmv_usd
    ,gmv_for_ratio
    ,direct_advv_cost
    ,broad_advv_cost
    ,direct_advv_gmv
    ,broad_advv_gmv
    ,revenue_usd / direct_advv_cost AS direct_cost_ratio
    ,revenue_usd / broad_advv_cost AS broad_cost_ratio
    ,ads_gmv_usd / direct_advv_gmv AS direct_gmv_ratio
    ,broad_gmv_usd / broad_advv_gmv AS broad_gmv_ratio
    ,target_cir
    ,ads_click_cnt
    ,ads_imp_cnt
    ,ads_order_cnt
    ,ads_broad_order_cnt
    ,sum_deduction_price_usd / cnt_deduction_price AS avg_deduction_price_usd
    ,sum_bid_price_usd / cnt_bid_price AS avg_bid_price_usd
    ,sum_deduction_price_usd
    ,sum_bid_price_usd
    ,cnt_deduction_price
    ,cnt_bid_price
    ,(sum_deduction_price_usd / cnt_deduction_price) / (sum_bid_price_usd / cnt_bid_price) AS deduction_bid_ratio
    ,padvv_cost
    ,ads_total_location
    ,ads_imp_uu
    ,ads_click_uu
    ,ads_order_uu
    ,plt_total_imp_cnt
    ,plt_total_click_cnt
    ,plt_total_order_cnt
    ,plt_total_gmv
    ,IF(a.feature_group = 'all', plt_total_order_cnt, feature_total_order_cnt) AS feature_total_order_cnt
    ,IF(a.feature_group = 'all', plt_total_gmv, feature_total_gmv) AS feature_total_gmv
    ,IF(a.feature_group = 'all', plt_total_imp_cnt, feature_total_imp_cnt) AS feature_total_imp_cnt
    ,IF(a.feature_group = 'all', plt_total_click_cnt, feature_total_click_cnt) AS feature_total_click_cnt
    ,a.voucher_type
    ,a.valid_ads_imp_cnt
FROM
    ads_type_performance_${grass_region_without_quote} a
LEFT JOIN
    feature_performance_${grass_region_without_quote} b
ON
    a.feature_group = b.feature_group
LEFT JOIN
    platform_total_${grass_region_without_quote};
